R=Path('/workspace/imessage-recreations');P=R/'verification/fidelity-review/05-games-exit';A=R/'references/05-linq/assets/games-exit-review';src=np.array(Image.open(R/'references/05-linq/assets/root-games-measure/frame-0148.png').convert('RGB'))/255;native=np.array(Image.open(P/'check-v1/4.933.png').convert('RGB'))/255;art=np.array(Image.open(R/'outputs/05-linq/final-v10/assets/49cacff6721cbed3-v10-chess-preview.png').convert('RGB'))/255;x,y=351,158;h,w=art.shape[:2];C=native[y:y+h,x:x+w];B=np.clip((C-.3*art)/.7,0,1);S=src[y:y+h,x:x+w];positive=np.maximum(0,S-B)/np.maximum(.001,1-B);negative=np.maximum(0,B-S)/np.maximum(.001,B);required=np.maximum(positive.max(2),negative.max(2));alpha=np.clip(np.maximum(.38,required*1.05),0,1);mask=Image.new('L',(w*4,h*4),0);ImageDraw.Draw(mask).rounded_rectangle((0,0,w*4,h*4),radius=40*4,fill=255);m=np.array(mask.resize((w,h),Image.Resampling.LANCZOS))/255;alpha*=m;rgb=np.clip((S-B*(1-alpha[:,:,None]))/np.maximum(1e-5,alpha[:,:,None]),0,1);out=np.uint8(np.clip(np.dstack((rgb,alpha)),0,1)*255+.5);out[alpha<.001]=0;Image.fromarray(out).save(A/'chess-entry-color-pose-148.png');print('bounded entry pose',w,h,'rgba not whole-frame')
